import type { MedusaRequest, MedusaResponse } from "@medusajs/framework/http"
import { ContainerRegistrationKeys } from "@medusajs/framework/utils"
const actorId=(req:MedusaRequest)=>(req as any).auth_context?.actor_id||(req as any).auth_context?.auth_identity_id
async function sellerId(req:MedusaRequest,actor_id:string){const q=req.scope.resolve(ContainerRegistrationKeys.QUERY) as any;try{const {data}=await q.graph({entity:"seller_member",fields:["seller.id"],filters:{member_id:actor_id},pagination:{take:1}});return data?.[0]?.seller?.id||null}catch{return null}}
export async function GET(req:MedusaRequest,res:MedusaResponse){const spike=req.scope.resolve("spike") as any,actor=actorId(req);if(!actor)return res.status(401).json({message:"Unauthorized"});const seller_id=await sellerId(req,actor);const vendorRows=await spike.listSpikeVendorDeliverySettings({actor_id:actor},{take:1});const allowed=new Set<string>((vendorRows[0]?.office_ids||[]).map(String));const offices=(await spike.listSpikeDeliveryOffices({active:true},{take:500})).filter((o:any)=>!allowed.size||allowed.has(String(o.id)));const product_id=String((req.query as any)?.product_id||"");const assignments=product_id?await spike.listSpikeProductDeliveries({product_id},{take:1}):seller_id?await spike.listSpikeProductDeliveries({seller_id,active:true},{take:500}):[];res.json({offices,assignment:product_id?assignments[0]||null:null,assignments,seller_id})}
export async function POST(req:MedusaRequest,res:MedusaResponse){const spike=req.scope.resolve("spike") as any,actor=actorId(req);if(!actor)return res.status(401).json({message:"Unauthorized"});const seller_id=await sellerId(req,actor),b=(req.body||{}) as any,product_id=String(b.product_id||"");const ids=(Array.isArray(b.office_ids)?b.office_ids:[b.delivery_office_id]).map(String).filter(Boolean);if(!product_id)return res.status(400).json({message:"المنتج مطلوب"});if(!ids.length)return res.status(422).json({message:"مكتب التوصيل مطلوب ولا يمكن حفظ المنتج بدونه",field:"delivery_office_id"});if(typeof b.returnable!=="boolean")return res.status(422).json({message:"يجب تحديد هل المنتج قابل للإرجاع أم غير قابل",field:"returnable"});const offices=await spike.listSpikeDeliveryOffices({active:true},{take:500});for(const id of ids)if(!offices.some((o:any)=>String(o.id)===id))return res.status(422).json({message:"أحد مكاتب التوصيل غير صالح"});const rows=await spike.listSpikeProductDeliveries({product_id},{take:1});const payload={product_id,seller_id,delivery_office_id:ids[0],office_ids:ids,returnable:b.returnable,active:true};const assignment=rows.length?await spike.updateSpikeProductDeliveries({id:rows[0].id,...payload}):await spike.createSpikeProductDeliveries(payload);res.json({assignment})}
